/**
 * Large title block that opens a page (`design/components/hero.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/hero.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/hero.module.css'
import { Inline, type InlineProps } from '../layout/Inline'

export type HeroAlign = NonNullable<HeroProps['align']>

/** Large title block that opens a page: the inputs it takes, by the React member's prop names. */
export interface HeroProps {
  align?: 'start' | 'center'
  lede?: string
  title: string
}

/** Large title block that opens a page. */
@Component({
  selector: 'pm-hero',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate, Inline],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<section
[attr.class]="e1()"
[attr.data-align]="e2()"
data-member="hero"
><!-- title -->
<h1
[attr.class]="e3()"
>{{ e4() }}</h1>
@if (e5()) {<!-- lede -->
<p
[attr.class]="e6()"
>{{ e7() }}</p>}
@if (e8()) {<pm-inline
[gap]="e9()"
[wrap]="e10()"
[justify]="e11()"
><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline>}</section>`,
})
export class Hero {
  readonly align = input<Exclude<HeroProps['align'], undefined>, HeroProps['align']>('start', {
    transform: (value: HeroProps['align']) => (value === undefined ? 'start' : value),
  })
  readonly lede = input<HeroProps['lede']>(undefined)
  readonly title = input.required<HeroProps['title']>()
  protected readonly $ = useMember({
    events: [],
    props: { align: () => this.align(), lede: () => this.lede(), title: () => this.title() },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.hero
  }

  protected e2() {
    return this.$p.align
  }

  protected e3() {
    return styles.title
  }

  protected e4() {
    return this.$p.title
  }

  protected e5() {
    return this.$p.lede !== undefined
  }

  protected e6() {
    if (!(this.$p.lede !== undefined)) return undefined as never
    return styles.lede
  }

  protected e7() {
    if (!(this.$p.lede !== undefined)) return undefined as never
    return this.$p.lede
  }

  protected e8() {
    return this.$.filled('actions')
  }

  protected e9(): InlineProps['gap'] {
    if (!this.$.filled('actions')) return undefined as never
    return 3
  }

  protected e10(): InlineProps['wrap'] {
    if (!this.$.filled('actions')) return undefined as never
    return true
  }

  protected e11(): InlineProps['justify'] {
    if (!this.$.filled('actions')) return undefined as never
    return this.$p.align === 'center' ? 'center' : 'start'
  }
}
